arguments.command:
python -c "
import xml.dom.minidom as md
doc = md.parse('unpacked_quarterly/word/document.xml')
ps = doc.getElementsByTagName('w:p')
for i, p in enumerate(ps):
    parts = []
    for t in p.getElementsByTagName('w:t'):
        if t.firstChild is not None:
            parts.append(t.firstChild.nodeValue)
    txt = ''.join(parts)
    if txt.strip():
        print(i, repr(txt))
"
